import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    p = int(data[1])
    s = list(data[2])

    chars = [chr(ord('a') + i) for i in range(p)]

    def is_valid(idx):
        if idx >= 1 and s[idx] == s[idx - 1]:
            return False
        if idx >= 2 and s[idx] == s[idx - 2]:
            return False
        return True

    pos = n - 1
    while pos >= 0:
        current_char_idx = ord(s[pos]) - ord('a')
        found = False
        for next_char_idx in range(current_char_idx + 1, p):
            candidate = chars[next_char_idx]
            s[pos] = candidate
            if is_valid(pos):
                found = True
                break

        if found:
            for i in range(pos + 1, n):
                for c in chars:
                    s[i] = c
                    if is_valid(i):
                        break
            print("".join(s))
            return
        pos -= 1

    print("NO")

if __name__ == "__main__":
    solve()
